create or replace TABLE KFL_PRODUCTION.DBP_DATA.WERBUNG_KENNZAHLEN_WOCHE_1 cluster by (
     MANDANT_ID,
     KJWO 
)(
	MANDANT_ID NUMBER(38,0) NOT NULL COMMENT 'Mandant_1 im DWH',
	KJWO NUMBER(38,0) NOT NULL COMMENT 'Kalenderjahreswoche. Format JJJJWW. Fuer DE die Woche_1, in der die Werbung endet. Fuer KMO die Woche_1, in der die Werbung beginnt.',
	WUP_ID NUMBER(38,0) NOT NULL COMMENT 'Mutter Wup_1 ID wird verwendet für Beziehung Lager zu Verteilzentrum.',
	NB_ID NUMBER(38,0) NOT NULL COMMENT 'Im bisherigen System die 4 Stelle der Marktnummer die Nebenbetriebskennziffer.',
	ART_ID NUMBER(38,0) NOT NULL COMMENT 'Input: Artikel_1 - Id einschliesslich der Generationen - ID (9-stellig); Output: 7stellige L&S-ID + Counter = 8stellige ArtikelID. WWNNNNPC (Warengruppe, Nummer, Pruefziffer, Counter) Regel: Neuer Artikel_1 -> Counter +1.',
	WERBE_TYP_ID NUMBER(38,0) NOT NULL COMMENT 'Typ der Werbung (Woche_1, Wochenanfang etc). Keine Lookup-Tabelle vorhanden.',
	MENGE_TAG1 NUMBER(9,3) NOT NULL DEFAULT 0 COMMENT 'Abverkaufsmenge am ersten Tag_1 der Werbung / Total sales_1 volume of the 1st day of the promotion + the 1st day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 1st + 8th+15th day',
	MENGE_TAG2 NUMBER(9,3) NOT NULL DEFAULT 0 COMMENT 'Abverkaufsmenge am zweiten Tag_1 der Werbung. / Total sales_1 volume of the 2nd day of the promotion + the 2nd day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 2nd + 9th+16th day',
	MENGE_TAG3 NUMBER(9,3) NOT NULL COMMENT 'Abverkaufsmenge am dritten Tag_1 der Werbung. / Total sales_1 volume of the 3rd day of the promotion + the 3rd day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 3rd + 10th+17th day',
	MENGE_TAG4 NUMBER(9,3) NOT NULL COMMENT 'Abverkaufsmenge am vierten Tag_1 der Werbung. / Total sales_1 volume of the 4th day of the promotion + the 4th day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 4th + 11th+18th day',
	MENGE_TAG5 NUMBER(9,3) NOT NULL COMMENT 'Abverkaufsmenge am fuenften Tag_1 der Werbung. / Total sales_1 volume of the 5th day of the promotion + the 5th day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 5th + 12th+19th day',
	MENGE_TAG6 NUMBER(9,3) NOT NULL COMMENT 'Abverkaufsmenge am sechsten Tag_1 der Werbung. / Total sales_1 volume of the 6th day of the promotion + the 6th day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 6th + 13th ... day',
	MENGE_TAG7 NUMBER(9,3) NOT NULL COMMENT 'Abverkaufsmenge am siebten Tag_1 der Werbung. / Total sales_1 volume of the 7th day of the promotion + the 7th day of every following week of the promotion.\n            For Promotions that last more than a week this is the total volume of sales_1 on 7th + 14th...',
	MENGE_NUR_TAG1 NUMBER(9,3) COMMENT 'Abverkaufsmenge nur am ersten Tag_1 der Werbung / Total sales_1 volume ONLY of the 1st day of the promotion. If the promotion is longer than a week, this is still only the amount on the 1st day. (8th, and 15th day are NOT included)',
	TAGE_MENGE_0 NUMBER(38,0) NOT NULL COMMENT 'Anzahl der Tage ohne Abverkauf.',
	MENGE_ENDBESTAND NUMBER(18,3) NOT NULL COMMENT 'Bestandsmenge am Ende der Aktion.',
	MENGE_AKTIONSSTART NUMBER(18,3) NOT NULL COMMENT 'Bestandsmenge zum Beginn der Aktion.',
	UMSATZ_NETTO_TAG1 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am ersten Tag_1 der Werbung.',
	UMSATZ_NETTO_TAG2 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am zweiten Tag_1 der Werbung.',
	UMSATZ_NETTO_TAG3 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am dritten Tag_1 der Werbung.',
	UMSATZ_NETTO_TAG4 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am vierten Tag_1 der Werbung.',
	UMSATZ_NETTO_TAG5 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am fuenften Tag_1 der Werbung.',
	UMSATZ_NETTO_TAG6 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am sechsten Tag_1 der Werbung.',
	UMSATZ_NETTO_TAG7 NUMBER(18,4) NOT NULL COMMENT 'Nettoumsatz am siebten Tag_1 der Werbung.',
	WE_MENGE NUMBER(18,3) NOT NULL COMMENT 'Wareneingang in der Werbewoche.',
	MIN_SICHERH_BESTAND NUMBER(18,3) NOT NULL COMMENT 'Menge, die unterste Grenze für den Sicherheitsbestand angibt. angereichert aus art_wup_status_per.',
	POSTEN_ID VARCHAR(2) NOT NULL COLLATE 'en-ci' COMMENT 'Eindeutige Kennzeichnung des Postenartikels, z.Bsp. PN. Redundant zu art_1, aufgrund Historisierung hier gespeichert.',
	WE_MENGE_ZENTRAL NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Wareneingang in der Werbewoche und der Vorwoche, nur zentrale Bestellarten.',
	FAKTOR_FLAKI NUMBER(9,6) NOT NULL COMMENT 'Umrechnungsfaktor Flasche in Kiste.',
	MUTTER_WB_ID NUMBER(38,0) NOT NULL COMMENT 'Artikelnummer des Mutter-Werbeartikels ist hier festgeschrieben. Bei Waisen ist die eigene Artikelnummer enthalten.',
	WTAG_ID_START NUMBER(38,0) NOT NULL COMMENT 'Wochentag ID des Werbestarts, von 1 bis 7, wobei 1 = Montag und 7 = Sonntag.',
	WTAG_ID_ENDE NUMBER(38,0) NOT NULL COMMENT 'Wochentag ID des Werbeendes, von 1 bis 7, wobei 1 = Montag und 7 = Sonntag.',
	MENGE_HISTORIE_AF NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Durchschnittliche Abverkaufsmenge der letzten 6 aktionsfreien Wochen.',
	ANZAHL_NULLBESTAND NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Tage mit Nullbestand waehrend des Aktionszeitraums.',
	ANZAHL_TAGE_AKTION NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Tage der Aktion.',
	MENGE_TAG1_7BIS13H NUMBER(9,3) NOT NULL DEFAULT 0 COMMENT 'Abverkaufsmenge am ersten Tag_1 der Werbung von 7 bis 13 Uhr.',
	LAGER_PROZENT NUMBER(38,0) NOT NULL DEFAULT 100 COMMENT 'Lagerprozentsatz. Gibt an, wieviel Prozent der Restlaufzeit noch nicht abgelaufen sein darf, wenn der Artikel_1 vom Lager ausgeliefert wird (wird redundant aus der Tabelle art_1 geladen).',
	MHD_ZEITRAUM NUMBER(38,0) COMMENT 'Dieses Feld gibt den standardmaessigen Mindesthaltbarkeitszeitraum fuer diesen Artikel_1 in Tagen an (wird redundant aus der Tabelle art_1 geladen).',
	SOLLBESTAND NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Sollbestand (wird redundant aus der Tabelle art_wup_status_per_1 geladen).',
	MENGE_BESTAND_SOLL_MAX NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Maximaler Sollbestand (PRWOG) (wird redundant aus der Tabelle art_wup_nachschub_per_1 geladen).',
	WERBENACHVERMARKTUNG_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag: Nachvermarktung des Werbeartikel (Verlaengerung Werbezeitraum).',
	WE_MENGE_VOR_AKTION NUMBER(18,3) NOT NULL DEFAULT 0 COMMENT 'Wareneingang vor Aktion.',
	ART_MUTTER_BEZUGSWEG_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Bezugsweg Werbemutter.',
	ANZAHL_NULLBESTAND_TAG1 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am ersten Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their first day)',
	ANZAHL_NULLBESTAND_TAG2 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am 2nd  Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their second day)',
	ANZAHL_NULLBESTAND_TAG3 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am 3rd  Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their third day)',
	ANZAHL_NULLBESTAND_TAG4 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am 4th  Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their fourth  day)',
	ANZAHL_NULLBESTAND_TAG5 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am 5th  Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their 5th  day)',
	ANZAHL_NULLBESTAND_TAG6 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am 6th  Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on their 6th day)',
	ANZAHL_NULLBESTAND_TAG7 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestände am 7th  Aktions-Wochentag fuer den Artikel_1, bei Gültigkeit > 1 Woche_1 können Werte > 1 entstehen (how many weeks of the promotion had zero stock on 7th day)',
	ANZAHL_NULLBESTAND_TAG1BIS3 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Nullbestand in den ersten drei Aktion5th Aktionstag stagen fuer den Artikel_1 innerhalb der Kalenderwoche (kjwo).',
	ANZAHL_MINUSBESTAND NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Tage mit Minusbestand waehrend des Aktionszeitraums.',
	ANZAHL_MINUSBESTAND_TAG1 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Minusbestand am ersten Tag_1 des Aktionszeitraums.',
	ANZAHL_MINUSBESTAND_TAG1BIS3 NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Anzahl Tage mit Minusbestand waehrend der ersten drei Tage des Aktionszeitraums.',
	AVQ_RELEVANT_FG NUMBER(38,0) COMMENT 'Flag: Datensatz relevant fuer Abverkaufsquote, AVQ (normale Aktion_1  = 1, BBY + Kundenkarte = 0).',
	WRG_ID VARCHAR(3) COMMENT 'Kurzbezeichnung der Währung, z.Bsp. CZK, EUR',
	MENGE_SA NUMBER(9,3) COMMENT 'Absatz Menge nur SA (Sonderaktion)',
	VK_VOR_AKTION_BRUTTO NUMBER(9,3) COMMENT 'Verkaufspreis Brutto vor Aktion_1',
	VK_AKTION_BRUTTO NUMBER(9,3) COMMENT 'Verkaufspreis Brutto in Aktion_1',
	VK_KCARD_BRUTTO NUMBER(9,3) COMMENT 'Verkaufspreis Brutto in Aktion_1 für K-CARD Inhaber',
	TD_UPDATE TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	TD_INSERT TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
	constraint PK_WERBUNG_KENNZAHLEN_WOCHE primary key (MANDANT_ID, KJWO, WUP_ID, NB_ID, ART_ID, WERBE_TYP_ID)
)COMMENT='AIS - Aggregat ueber Aktionsartikel- Abverkauf und Bestand pro Woche. Nur Artikel_1, die speziellen Kriterien genuegen.'
;